message.content:
You are consolidating black-box probe findings about Python's jsonschema Draft7Validator + ErrorTree into ONE implementation spec for a JavaScript reimplementation.

Here are the raw findings from 7 probe agents (JSON):

[
 {
  "family": "\"type\" keyword and the underlying type system (Draft7Validator + ErrorTree), test18_executable",
  "rules": [
   {
    "rule": "Output shape is fixed: line1=ErrorTree.total_errors, line2=line3=raw len(iter_errors), lines4-6 = Python bool literal `True`/`False` (capital T/F) and always equal to (rawCount==0), lines7-8 = literal `None`, lines9-10 = same value as line1. Exit 0. Any exception anywhere => completely EMPTY stdout, exit 1 (argparse failures give exit 2).",
    "evidence": "--a 1 --b '{\"type\":\"integer\"}' -> 0,0,0,True,True,True,None,None,0,0 EXIT=0 ; --a 1 --b '{\"type\":\"null\"}' -> 1,1,1,False,False,False,None,None,1,1 EXIT=0",
    "confidence": "certain"
   },
   {
    "rule": "A failing `type` keyword produces EXACTLY ONE error at that instance node, regardless of how many type names are listed in the array.",
    "evidence": "--a '{}' --b '{\"type\":[\"string\",\"number\",\"boolean\",\"null\",\"array\",\"integer\"]}' -> 1,1,1,False,False,False,None,None,1,1 ; --a '{}' --b '{\"type\":[\"string\",\"number\",\"boolean\"]}' -> 1,1,1,...",
    "confidence": "certain"
   },
   {
    "rule": "Type membership table (instance -> which of the 7 names it satisfies): null->null; true/false->boolean ONLY (never number, never integer); JSON object->object; JSON array->array; string->string; int literal->number AND integer; float literal->number, and ALSO integer iff its float value has zero fractional part.",
    "evidence": "--a true --b '{\"type\":\"number\"}' -> 1,1,1,False,... ; --a true --b '{\"type\":\"integer\"}' -> 1,1,1,False,... ; --a 1.0 --b '{\"type\":\"integer\"}' -> 0,0,0,True,... ; --a 2.0 --b '{\"type\":\"integer\"}' -> 0,...,True ; --a 1.5 --b '{\"type\":\"integer\"}' -> 1,1,1,False,...",
    "confidence": "certain"
   },
   {
    "rule": "Draft7 zero-fraction rule details: -0.0, 1e2, 1.0e0, 1e308 are all `integer`. 0.1 and -1.5 are not. 1.00000000000000001 and 1.0000000000000000000000001 ARE integer (they round to 1.0 in float64, so test the PARSED double, not the source text).",
    "evidence": "--a=-0.0 -b '{\"type\":\"integer\"}' -> 0,...,True ; --a 1e2 -> True ; --a 1e308 -> True ; --a 1.00000000000000001 -> True ; --a 0.1 -> 1,1,1,False ; --a=-1.5 -> 1,1,1,False",
    "confidence": "certain"
   },
   {
    "rule": "Overflowing float literals become Infinity: 1e400 / -1e400 / Infinity / -Infinity are `number` but NOT `integer`. NaN is `number` but NOT `integer`. (Python json.loads accepts the bare tokens NaN, Infinity, -Infinity — a strict JSON.parse in JS will throw instead; you must special-case these tokens.)",
    "evidence": "--a 1e400 --b '{\"type\":\"number\"}' -> 0,...,True ; --a 1e400 --b '{\"type\":\"integer\"}' -> 1,1,1,False ; --a NaN --b '{\"type\":\"number\"}' -> True ; --a NaN --b '{\"type\":\"integer\"}' -> 1,1,1,False ; --a=-Infinity --b '{\"type\":\"number\"}' -> 0,...,True",
    "confidence": "certain"
   },
   {
    "rule": "Integers are arbitrary precision and EXACT — no float64 rounding. Comparisons (const/enum/maximum) on >2^53 integers must be done with BigInt/decimal-string semantics in JS.",
    "evidence": "--a 10000000000000000001 --b '{\"const\":10000000000000000000}' -> 1,1,1,False (they differ) ; --a 10000000000000000001 --b '{\"const\":10000000000000000001}' -> 0,...,True ; --a 9007199254740993 --b '{\"const\":9007199254740992}' -> 1,1,1,False ; --a 10000000000000000001 --b '{\"type\":\"integer\"}' -> True ; --a 123456789012345678901234567890 --b '{\"type\":\"integer\"}' -> True",
    "confidence": "certain"
   },
   {
    "rule": "ErrorTree collapse key = (absolute instance path, validator keyword). Two errors sharing BOTH collapse into one; different keyword at the same path does NOT collapse. total_errors is computed recursively: node.total = (#distinct keywords among errors whose remaining path is empty at this node) + sum(child.total).",
    "evidence": "COLLAPSE: --a null --b '{\"allOf\":[{\"type\":\"string\"},{\"type\":\"number\"}]}' -> 1,2,2,False,False,False,None,None,1,1 ; --a null --b '{\"allOf\":[{\"type\":\"string\"},{\"type\":\"number\"},{\"type\":\"array\"}]}' -> 1,3,3,...,1,1 ; NO COLLAPSE (different keywords): --a 3 --b '{\"type\":\"string\",\"enum\":[1,2]}' -> 2,2,2,... ; RECURSIVE SUM: --a '{\"a\":1,\"b\":1}' --b '{\"allOf\":[{\"properties\":{\"a\":{\"type\":\"string\"},\"b\":{\"type\":\"string\"}}},{\"properties\":{\"a\":{\"type\":\"boolean\"},\"b\":{\"type\":\"boolean\"}}}]}' -> 2,4,4,False,False,False,None,None,2,2",
    "confidence": "certain"
   },
   {
    "rule": "More confirmed line1<line2 (collapse) generators, all reducing N same-path same-keyword errors to 1: root `type` + allOf types; properties+patternProperties both hitting the same key with the same keyword; $ref merged with a sibling keyword under allOf; propertyNames with several bad names; dependencies array with several missing props; nested items+allOf.",
    "evidence": "--a 1 --b '{\"type\":\"string\",\"allOf\":[{\"type\":\"boolean\"},{\"type\":\"array\"}]}' -> 1,3,3,...,1,1 ; --a '{\"a\":1}' --b '{\"properties\":{\"a\":{\"type\":\"string\"}},\"patternProperties\":{\"^a\":{\"type\":\"boolean\"}}}' -> 1,2,2,...,1,1 (but with `{\"enum\":[9]}` instead of the boolean type -> 2,2,2,...,2,2) ; --a '{\"aa\":1,\"bb\":2}' --b '{\"propertyNames\":{\"maxLength\":1}}' -> 1,2,2,...,1,1 ; --a '{\"a\":1}' --b '{\"dependencies\":{\"a\":[\"b\",\"c\"]}}' -> 1,2,2,...,1,1 ; --a '[[1]]' --b '{\"items\":{\"allOf\":[{\"items\":{\"type\":\"string\"}},{\"items\":{\"type\":\"boolean\"}}]}}' -> 1,2,2,...,1,1 ; --a '{\"a\":1}' --b '{\"allOf\":[{\"properties\":{\"a\":{\"type\":\"string\"}}},{\"properties\":{\"a\":{\"type\":\"boolean\"}}}]}' -> 1,2,2,...,1,1",
    "confidence": "certain"
   },
   {
    "rule": "anyOf / oneOf / not / contains / if-then wrap their sub-errors: they emit exactly ONE error at the parent node (children are not surfaced by iter_errors), so no collapse and count is 1.",
    "evidence": "--a null --b '{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"number\"}]}' -> 1,1,1,... ; --a null --b '{\"oneOf\":[{\"type\":\"string\"},{\"type\":\"string\"}]}' -> 1,1,1,... ; --a '\"x\"' --b '{\"oneOf\":[{\"type\":\"string\"},{\"type\":\"string\"}]}' -> 1,1,1,False (2 matches = oneOf failure) ; --a '[1,2]' --b '{\"contains\":{\"type\":\"string\"}}' -> 1,1,1,... ; --a 1 --b '{\"if\":{\"type\":\"integer\"},\"then\":{\"type\":\"string\"}}' -> 1,1,1,...",
    "confidence": "certain"
   },
   {
    "rule": "allOf and $ref do NOT wrap: their sub-errors are surfaced individually with the parent's instance path, which is the main source of collapse.",
    "evidence": "--a 1 --b '{\"allOf\":[{\"$ref\":\"#/definitions/s\"},{\"type\":\"boolean\"}],\"definitions\":{\"s\":{\"type\":\"string\"}}}' -> 1,2,2,False,False,False,None,None,1,1",
    "confidence": "certain"
   },
   {
    "rule": "`type` MUST be either a simpleType string or a non-empty array of UNIQUE simpleType strings, ANYWHERE in the schema (including unreached subschemas, `definitions`, and `not`). Otherwise check_schema raises SchemaError => EMPTY, exit 1. Legal names are exactly: null, boolean, object, array, number, string, integer (case-sensitive, no surrounding whitespace).",
    "evidence": "'{\"type\":[]}' -> EMPTY exit=1 (SchemaError: [] is not valid under any of the given schemas, metaschema['properties']['type'] minItems 1) ; '{\"type\":[\"integer\",\"integer\"]}' -> EMPTY exit=1 (uniqueItems) ; '{\"type\":\"Integer\"}', '{\"type\":\"int\"}', '{\"type\":\"NUMBER\"}', '{\"type\":\"integer \"}', '{\"type\":\" integer\"}', '{\"type\":{}}' -> EMPTY exit=1 ; --a 1 --b '{\"type\":\"integer\",\"definitions\":{\"x\":{\"type\":\"int\"}}}' -> EMPTY exit=1 ; --a 1 --b '{\"type\":\"integer\",\"not\":{\"type\":\"int\"}}' -> EMPTY exit=1",
    "confidence": "certain"
   },
   {
    "rule": "`type` as a non-string, non-list scalar (number / null / true / false) crashes EARLIER, at iter_errors, with TypeError \"'X' object is not iterable\" (jsonschema/_keywords.py line 285) — still EMPTY exit 1. `type` as an object {} is iterated over its KEYS instead (dict is iterable), so it does not TypeError; it fails later at check_schema.",
    "evidence": "--a 1 --b '{\"type\":1}' -> EMPTY exit=1, stderr: File jsonschema/_keywords.py line 285 in type / TypeError: 'int' object is not iterable ; '{\"type\":null}' -> TypeError: 'NoneType' object is not iterable ; '{\"type\":true}' -> TypeError: 'bool' object is not iterable ; '{\"type\":{}}' -> SchemaError at validators.py line 317 check_schema",
    "confidence": "certain"
   },
   {
    "rule": "Evaluation ORDER is observable: iter_errors runs BEFORE check_schema (test18.py line 17 vs line 33). The unknown-type lookup inside `type` is a short-circuiting any(), so an unknown type name only raises UnknownType at iter_errors if it is actually REACHED (i.e. no earlier listed name matched the instance). Otherwise the SchemaError from check_schema fires instead. Both give EMPTY exit 1, so the distinction is only visible on stderr — a JS reimplementation can treat all invalid `type` as exit 1.",
    "evidence": "--a '\"x\"' --b '{\"type\":[\"string\",\"int\"]}' -> EMPTY exit=1, stderr: test18.py line 33 -> validators.py:317 check_schema -> SchemaError ; --a 1 --b '{\"type\":[\"string\",\"int\"]}' -> EMPTY exit=1, stderr: _keywords.py:285 -> UnknownType: Unknown type 'int' ; --a '\"x\"' --b '{\"type\":[\"int\",\"string\"]}' -> UnknownType (int checked first)",
    "confidence": "certain"
   },
   {
    "rule": "Sibling keywords are applied INDEPENDENTLY of a failing `type`; a type error does not suppress other keyword errors at the same node. Each applicable keyword adds its own error.",
    "evidence": "--a '\"abc\"' --b '{\"type\":\"integer\",\"minLength\":10}' -> 2,2,2,False,... ; --a '[1]' --b '{\"type\":\"object\",\"minItems\":5}' -> 2,2,2,... ; --a '{\"a\":1}' --b '{\"type\":\"array\",\"required\":[\"b\"],\"minProperties\":5}' -> 3,3,3,...",
    "confidence": "certain"
   },
   {
    "rule": "Each keyword self-gates on the instance's type and silently passes for non-applicable types. Booleans are exempt from ALL numeric keywords (they are not `number`).",
    "evidence": "--a true --b '{\"exclusiveMinimum\":5,\"multipleOf\":2,\"maximum\":0}' -> 0,0,0,True,... ; --a true --b '{\"maxLength\":0,\"minLength\":3,\"pattern\":\"^z$\"}' -> True ; --a true --b '{\"minItems\":3,\"maxItems\":0,\"uniqueItems\":true}' -> True ; --a true --b '{\"required\":[\"a\"],\"minProperties\":2}' -> True ; --a 1 --b '{\"maxLength\":0,\"minItems\":5,\"required\":[\"a\"]}' -> True ; --a '\"abc\"' --b '{\"minimum\":5,\"minItems\":5,\"required\":[\"a\"]}' -> True",
    "confidence": "certain"
   },
   {
    "rule": "Equality for const/enum/uniqueItems: 1 == 1.0 (numeric equality, cross int/float), but booleans are NEVER equal to numbers, at any nesting depth (special bool-vs-number guard in the deep comparison).",
    "evidence": "--a 1 --b '{\"const\":1.0}' -> 0,...,True ; --a 1.0 --b '{\"const\":1}' -> True ; --a true --b '{\"const\":1}' -> 1,1,1,False ; --a true --b '{\"enum\":[1]}' -> 1,1,1,False ; --a 1 --b '{\"enum\":[true]}' -> 1,1,1,False ; --a '[true]' --b '{\"enum\":[[1]]}' -> 1,1,1,False ; --a '{\"a\":true}' --b '{\"const\":{\"a\":1}}' -> 1,1,1,False ; --a '{\"a\":1}' --b '{\"const\":{\"a\":1.0}}' -> 0,...,True ; --a '[1,true]' --b '{\"uniqueItems\":true}' -> True (distinct) ; --a '[0,false]' --b '{\"uniqueItems\":true}' -> True (distinct) ; --a '[1,1.0]' --b '{\"uniqueItems\":true}' -> 1,1,1,False (duplicate)",
    "confidence": "certain"
   },
   {
    "rule": "String length is measured in Unicode CODE POINTS (Python semantics), not UTF-16 units. An astral character counts as 1.",
    "evidence": "--a '\"😀\"' --b '{\"maxLength\":1}' -> 0,...,True ; --a '\"😀\"' --b '{\"minLength\":2}' -> 1,1,1,False ; --a '\"𐀀\"' --b '{\"maxLength\":1}' -> True ; --a '\"ab\"' --b '{\"maxLength\":1}' -> 1,1,1,False",
    "confidence": "certain"
   },
   {
    "rule": "Schema must be a JSON object or a JSON boolean. `true` = always valid, `false` = 1 error at the node. Any other top-level schema JSON (array, null, string, number) crashes during Draft7Validator construction/first use with AttributeError/TypeError from referencing/_legacy_dollar_id => EMPTY exit 1.",
    "evidence": "--a 1 --b true -> 0,...,True ; --a 1 --b false -> 1,1,1,False,... ; --a 1 --b '{}' -> 0,...,True ; --a '{\"a\":1}' --b '{\"properties\":{\"a\":false}}' -> 1,1,1,False ; --a 1 --b '[]' -> EMPTY exit=1 (AttributeError: 'list' object has no attribute 'get') ; --b null -> TypeError: argument of type 'NoneType' is not iterable ; --b '\"x\"' -> AttributeError 'str' ; --b 1 -> TypeError 'int'",
    "confidence": "certain"
   },
   {
    "rule": "Unknown/misspelled keywords are ignored (no error, no schema error). Keyword names are case-sensitive.",
    "evidence": "--a 1 --b '{\"typo\":\"x\"}' -> 0,...,True ; --a 1 --b '{\"Type\":\"string\"}' -> 0,...,True ; --a 1 --b '{\"type\":\"integer\",\"unknownKw\":{\"type\":\"string\"}}' -> 0,...,True",
    "confidence": "certain"
   },
   {
    "rule": "`$schema` is ignored for dialect selection — Draft-7 semantics and the Draft-7 metaschema are always used, even for a draft-04 or bogus $schema value. Consequently draft-04-only forms like boolean `exclusiveMinimum` are a SchemaError.",
    "evidence": "--a 1.0 --b '{\"$schema\":\"http://json-schema.org/draft-04/schema#\",\"type\":\"integer\"}' -> 0,...,True (draft7 zero-fraction rule still applied) ; --a 1 --b '{\"$schema\":\"bogus\",\"type\":\"integer\"}' -> 0,...,True ; --a 1 --b '{\"type\":\"integer\",\"exclusiveMinimum\":true,\"minimum\":5}' -> EMPTY exit=1",
    "confidence": "certain"
   },
   {
    "rule": "Instance JSON parsing uses Python json.loads: duplicate object keys -> last one wins; leading/trailing whitespace OK; lone surrogates in \\uXXXX escapes are accepted; but leading zeros (01), single quotes, `undefined`, and empty string are parse errors => EMPTY exit 1.",
    "evidence": "--a '{\"a\":1,\"a\":2}' --b '{\"properties\":{\"a\":{\"type\":\"string\"}}}' -> 1,1,1,False (one error, value 2) ; --a '  1  ' --b '{\"type\":\"integer\"}' -> 0,...,True ; --a '\"\\ud800x\"' --b '{\"maxLength\":2,\"minLength\":2}' -> 0,...,True ; --a 01 -> EMPTY exit=1 (JSONDecodeError) ; --a \"'x'\" -> EMPTY exit=1 ; --a '' -> EMPTY exit=1 ; --a undefined -> EMPTY exit=1",
    "confidence": "certain"
   },
   {
    "rule": "Array-index and object-key path components both key the ErrorTree; per-item/per-property errors do NOT collapse across different indices/keys.",
    "evidence": "--a '[1,2]' --b '{\"items\":{\"type\":\"string\"}}' -> 2,2,2,...,2,2 ; --a '[1,2,3]' --b '{\"items\":{\"type\":\"string\"}}' -> 3,3,3,...,3,3 ; --a '{\"a\":1,\"b\":2}' --b '{\"properties\":{\"a\":{\"type\":\"string\"},\"b\":{\"type\":\"string\"}}}' -> 2,2,2,...,2,2 ; --a '[{\"a\":1},{\"a\":2}]' --b '{\"items\":{\"properties\":{\"a\":{\"type\":\"string\"}}}}' -> 2,2,2,...,2,2",
    "confidence": "certain"
   },
   {
    "rule": "A node's own error and its descendants' errors both count toward total_errors (parent contributes its own keyword set plus the recursive sum of children).",
    "evidence": "--a '{\"a\":1}' --b '{\"type\":\"string\",\"properties\":{\"a\":{\"type\":\"string\"}}}' -> 2,2,2,False,False,False,None,None,2,2 (1 root type error + 1 child type error)",
    "confidence": "certain"
   },
   {
    "rule": "argparse artifact, not program logic: a value beginning with '-' that does not match ^-\\d+$ or ^-\\d*\\.\\d+$ is treated as an option and the process exits 2 with EMPTY stdout. Use --a=<value>. Missing --a/--b or no args also exit 2.",
    "evidence": "--a '-1e400' --b '{\"type\":\"integer\"}' -> EMPTY exit=2 ; --a='-1e400' --b '{\"type\":\"integer\"}' -> 1,1,1,False,...  ; --a '-0.0' (space form) works -> 0,...,True ; --a '-Infinity' -> EMPTY exit=2 but --a='-Infinity' -> 0,...,True ; missing --b -> exit=2 ; no args -> exit=2",
    "confidence": "certain"
   }
  ],
  "surprises": [
   "`1.0` IS an `integer` in Draft 7 (any float with zero fractional part), including -0.0, 1e2, 1e308, and 1.00000000000000001 (which rounds to 1.0). A naive JS `Number.isInteger` check on the raw token, or a 'has a decimal point => not integer' rule, gets this wrong.",
   "`1e400` and `NaN` are `number` but NOT `integer` (they become inf/nan and fail is_integer). Also, Python json.loads ACCEPTS the bare tokens NaN, Infinity, -Infinity, which strict JSON.parse in JS rejects.",
   "Booleans are never `number`/`integer`, AND they are exempt from every numeric/string/array/object keyword — `true` validates clean against {\"minimum\":5,\"multipleOf\":2,\"maxLength\":0,\"minItems\":3,\"required\":[\"a\"]}.",
   "Integers are arbitrary precision: 10000000000000000001 != 10000000000000000000 and 9007199254740993 != 9007199254740992. JS Number collapses both pairs, so const/enum/maximum comparisons need BigInt or string-based comparison.",
   "ErrorTree collapses by (path, keyword): {\"allOf\":[{\"type\":\"string\"},{\"type\":\"number\"},{\"type\":\"array\"}]} on null gives line1=1 but line2=3. allOf and $ref surface child errors at the parent path (collapsible); anyOf/oneOf/not/contains/if-then wrap into a single parent error (never collapsible).",
   "An unknown type NAME anywhere in the schema — even in `definitions` or inside a `not` that is logically irrelevant — kills the whole run (exit 1), because check_schema validates the entire schema against the Draft-7 metaschema. But whether the failure comes from iter_errors (UnknownType) or check_schema (SchemaError) depends on the short-circuiting any(): {\"type\":[\"string\",\"int\"]} raises UnknownType for instance 1 and SchemaError for instance \"x\".",
   "`type` values that are ints/null/bools crash with TypeError 'not iterable' inside the type keyword BEFORE check_schema, while `type: {}` does not (a dict is iterable over its keys) and instead fails at check_schema. Duplicate entries ({\"type\":[\"integer\",\"integer\"]}) and empty arrays ({\"type\":[]}) are metaschema violations, not validation failures.",
   "String lengths are code points, so \"😀\" satisfies {\"maxLength\":1} and violates {\"minLength\":2}; JS `.length` gives 2 and inverts both results.",
   "A top-level schema of `[]`, `null`, `\"x\"`, or `1` crashes at validator construction (referencing/_legacy_dollar_id), not at validation — but `true`/`false` are perfectly valid boolean schemas.",
   "$schema is completely ignored for dialect selection: a draft-04 $schema still gets Draft-7 semantics and is still checked against the Draft-7 metaschema (so draft-04's boolean exclusiveMinimum is a hard SchemaError)."
  ],
  "crashCases": [
   "--a 1 --b '{\"type\":\"int\"}'  => EMPTY exit=1; jsonschema.exceptions.UnknownType: Unknown type 'int' for validator with schema: {'type': 'int'} (raised at test18.py:17 iter_errors -> _keywords.py:285 type -> validators.py:458 is_type)",
   "--a 1 --b '{\"type\":\"Integer\"}'  => EMPTY exit=1; UnknownType (case-sensitive)",
   "--a 1 --b '{\"type\":\"NUMBER\"}'  => EMPTY exit=1; UnknownType",
   "--a 1 --b '{\"type\":\"integer \"}' and --b '{\"type\":\" integer\"}'  => EMPTY exit=1; UnknownType (no whitespace trimming)",
   "--a 1 --b '{\"type\":[\"string\",1]}'  => EMPTY exit=1; jsonschema.exceptions.UnknownType: Unknown type 1 for validator with schema: {'type': ['string', 1]}",
   "--a 1 --b '{\"type\":[\"string\",\"int\"]}'  => EMPTY exit=1; UnknownType 'int' (iter_errors) — but with --a '\"x\"' the same schema instead fails at check_schema with SchemaError",
   "--a 1 --b '{\"type\":[\"integer\",\"int\"]}'  => EMPTY exit=1; SchemaError at check_schema ('int' not a simpleType; iter_errors short-circuited on 'integer')",
   "--a 1 --b '{\"type\":[]}'  => EMPTY exit=1; jsonschema.exceptions.SchemaError: [] is not valid under any of the given schemas (metaschema['properties']['type'] anyOf, minItems 1) at validators.py:317 check_schema (test18.py:33)",
   "--a 1 --b '{\"type\":[\"integer\",\"integer\"]}'  => EMPTY exit=1; SchemaError: ['integer', 'integer'] is not valid under any of the given schemas (uniqueItems)",
   "--a 1 --b '{\"type\":[\"string\",\"string\"]}'  => EMPTY exit=1; SchemaError (uniqueItems)",
   "--a 1 --b '{\"type\":{}}'  => EMPTY exit=1; SchemaError: {} is not valid under any of the given schemas (check_schema)",
   "--a 1 --b '{\"type\":{\"a\":1}}' and '{\"type\":{\"integer\":1}}'  => EMPTY exit=1 (dict iterated over keys; fails at check_schema)",
   "--a 1 --b '{\"type\":1}'  => EMPTY exit=1; TypeError: 'int' object is not iterable (jsonschema/_keywords.py:285 in type)",
   "--a 1 --b '{\"type\":null}'  => EMPTY exit=1; TypeError: 'NoneType' object is not iterable",
   "--a 1 --b '{\"type\":true}'  => EMPTY exit=1; TypeError: 'bool' object is not iterable",
   "--a 1 --b '{\"type\":\"integer\",\"definitions\":{\"x\":{\"type\":\"int\"}}}'  => EMPTY exit=1 (unreached subschema still fails check_schema)",
   "--a 1 --b '{\"type\":\"integer\",\"not\":{\"type\":\"int\"}}'  => EMPTY exit=1",
   "--a '{\"b\":1}' --b '{\"properties\":{\"a\":{\"type\":\"int\"}}}'  => EMPTY exit=1 (property 'a' absent, subschema never applied, still fails check_schema)",
   "--a 1 --b '{\"type\":\"integer\",\"exclusiveMinimum\":true,\"minimum\":5}'  => EMPTY exit=1; SchemaError (draft-04 boolean exclusiveMinimum invalid under Draft-7 metaschema)",
   "--a 1 --b '[]'  => EMPTY exit=1; AttributeError: 'list' object has no attribute 'get' (validators.py:289 __attrs_post_init__ -> referencing/jsonschema.py:56 _legacy_dollar_id)",
   "--a 1 --b 'null'  => EMPTY exit=1; TypeError: argument of type 'NoneType' is not iterable (referencing/jsonschema.py:54)",
   "--a 1 --b '\"x\"'  => EMPTY exit=1; AttributeError: 'str' object has no attribute 'get'",
   "--a 1 --b '1'  => EMPTY exit=1; TypeError: argument of type 'int' is not iterable",
   "--a 01 --b '{\"type\":\"integer\"}'  => EMPTY exit=1; json.decoder.JSONDecodeError (leading zero)",
   "--a \"'x'\" --b '{\"type\":\"string\"}'  => EMPTY exit=1; json.decoder.JSONDecodeError: Expecting value: line 1 column 1 (char 0)",
   "--a '' --b '{\"type\":\"string\"}'  => EMPTY exit=1; JSONDecodeError: Expecting value: line 1 column 1 (char 0)",
   "--a undefined --b '{\"type\":\"string\"}'  => EMPTY exit=1; JSONDecodeError",
   "--a '-1e400' --b '{\"type\":\"integer\"}'  => EMPTY exit=2 (argparse treats it as an option, NOT a Python exception; --a='-1e400' works and yields 1,1,1,False,...)",
   "--a '-Infinity' --b '{\"type\":\"number\"}'  => EMPTY exit=2 (argparse; --a='-Infinity' yields 0,...,True)",
   "(no args) and (--a 1 with --b omitted)  => EMPTY exit=2 (argparse usage error)"
  ]
 },
 {
  "family": "numeric keywords: multipleOf, maximum, minimum, exclusiveMaximum, exclusiveMinimum (Draft7Validator + ErrorTree, test18_executable)",
  "rules": [
